 ; boot.asm - A simple bootloader[bits 16][org 0x7C00]start:    ; Set up segment registers    cli    mov ax, 0x0000    mov ds, ax    mov es, ax    mov ss, ax    mov sp, 0x7C00    sti; Load kernel    mov ah, 0x02 ; BIOS read sector function    mov al, 0x01 ; Read one sector    mov ch, 0x00 ; Cylinder 0    mov cl, 0x02 ; Sector 2 (after boot sector)    mov dh, 0x00 ; Head 0    mov dl, 0x80 ; Drive 0 (First HDD)    mov bx, 0x7E00 ; Load address    int 0x13 ; Call BIOS interrupt; Jump to kernel    jmp 0x0000:0x7E00times 510-($-$$) db 0dw 0xAA55